-- S375 SkyTally, 2026-10-13. Rule 8 ingest through execute_sql: INSERT-only, idempotent on slug,
-- each row logged to cpl_memory_log (actor SkyTallyS375; verified creates = 1 for all six at write time).
-- Rollback: delete from public.cpl_memory where author = 'SkyTallyS375';
insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, source, related, status, author)
select x.slug, x.kind, 'cpl', x.title, x.summary, x.detail, x.plain, x.tags, x.source, coalesce(x.related, '{}'::text[]), x.status, 'SkyTallyS375'
from jsonb_to_recordset($json$[
 {"slug":"chrome-blur-on-removal-double-close-2026-10-13","kind":"pitfall","title":"Chrome blur re-entered the cell editors","summary":"Annual Goals cell editors commit on blur. Restoring a cell on Escape or Enter removes the focused input; Chrome fires its blur, blur commits, and the second restore throws mid-keydown. Every save and every Escape threw on the live page (the save still went out once). Fix: a done guard closes each field once; focus returns one tick later.","detail":"Found by npm run a11y's functional keyboard check (Escape left focus on body); jsdom never fires blur on removal, so the jsdom test passed. Fixed in cpl-project-tracker#2054. Any editor that commits on blur and replaces its own content needs the guard.","plain":"Pressing Escape or Enter in an Annual Goals cell made the page throw an error every time, because closing the box triggered a second close. It looked fine because the value still saved once. It only showed up in a real browser test, never in the simulated one.","tags":["workplan","annual-goals","a11y","pitfall","keyboard"],"source":"S375 SkyTally; cpl-project-tracker#2054; docs/workplan_annual_goals_lessons.md","status":"proposed"},
 {"slug":"static-scan-sees-only-literal-rest-urls-2026-10-13","kind":"pitfall","title":"Scanners see only literal table URLs","summary":"The dependency map and the Admin tab's surface map find a Supabase write by a literal '/rest/v1/<table>' with its method nearby. A helper that builds the URL from a variable hides the write: #2051's add flow listed workplan_activity_associations as a read. Name each table literally beside its method; a helper may check the response, never build the URL.","detail":"Caught only because cobi_admin_surface.js went stale in CI shard 1 on #2051 (admin_tab test). Fixed in commit 86d3b72.","plain":"The tools that list which tab writes to which table read the code as text. When the new add button built its addresses in a way the tools could not read, one table it writes to was listed as only being read, which would tell an admin it needs less protection than it does.","tags":["dependency-map","governance","admin-tab","pitfall","supabase"],"source":"S375 SkyTally; cpl-project-tracker#2051 commit 86d3b72","status":"proposed"},
 {"slug":"on-accent-not-white-in-dark-2026-10-13","kind":"pitfall","title":"Text on the navy takes --white","summary":"--on-accent turns near-black in the dark palette while --seal-blue stays the navy, so header text on var(--seal-blue) read 1.43:1 in dark. Text on --seal-blue takes var(--white), which the dark palette leaves alone (the statewide tabs already do this).","detail":null,"plain":"In dark mode one color name meant for text on accent colors flips to nearly black, but the dark blue header stays dark blue, so the column titles nearly vanished. Using the plain white color fixes it in both modes.","tags":["first-light","dark-mode","a11y","contrast","pitfall"],"source":"S375 SkyTally; npm run a11y on the Annual Goals preview; cpl-project-tracker#2054","status":"proposed"},
 {"slug":"workplan-move-function-built-not-applied-2026-10-13","kind":"milestone","title":"Move control built, not yet live","summary":"workplan_move_sub_activity re-keys a sub-activity in all seven id-keyed tables in one transaction, rolls back if any other public project_id/item_id/activity_id column still holds the old id, and files before-values in workplan_id_moves. Reviewer-only until Sam rules (Sheet 72 card 4). PR #2056 held as draft: not applied (Sheet 72 card 3).","detail":"Tables: projects (copied under the new id, since update_log's FK is not deferrable), update_log, item_raci, item_updates, project_lifecycle, workplan_goals, workplan_activity_associations; the new home link becomes primary, the old Activity link stays unless dropped. Verified with scripts/verify_workplan_move.js against Postgres 16 (PGlite): 22/22, including the 1.1.2 -> 4.2.1 move, refusals, guard rollback and undo. tests/workplan_move.test.js: 39 checks. Governance: tab:workplan-goals and rpc:workplan_move_sub_activity mapped to DR-13.","plain":"There is now a Move button design for the workplan that renumbers a sub-activity everywhere at once, refuses if anything would be left behind, and keeps an undo record. It is tested but not switched on: the database tool would not accept it, so Sam has the paste on the decision sheet.","tags":["workplan","annual-goals","move","supabase","governance"],"source":"S375 SkyTally; cpl-project-tracker#2056; kb/supabase_workplan_move.sql","related":["workplan-rekey-872-incomplete","sam-annual-goals-rulings-2026-10-12"],"status":"proposed"},
 {"slug":"pglite-tests-a-plpgsql-function-locally-2026-10-13","kind":"procedure","title":"Test SQL functions locally with PGlite","summary":"The sandbox cannot run a Postgres server. PGlite (Postgres 16 in WebAssembly, npm i --no-save @electric-sql/pglite@0.2.17) runs plpgsql, roles, grants and RLS in-process: create the live table shapes, stub auth.jwt() from a setting, run the committed .sql file, and check behavior before apply_migration.","detail":"Worked example: scripts/verify_workplan_move.js (S375). KB note: docs/kb-notes/playbook-test-a-database-function-locally-with-pglite.md. Postgres 16 is installed but refuses root, and an unprivileged user cannot reach the session scratchpad.","plain":"Before switching on a new database routine, a session can now run it against a throwaway copy of the database that lives inside the test program, so mistakes show up before anything touches the real data.","tags":["supabase","testing","procedure","sql"],"source":"S375 SkyTally; scripts/verify_workplan_move.js","status":"proposed"},
 {"slug":"apply-migration-timeouts-2026-10-13","kind":"risk","title":"apply_migration still timing out","summary":"S375, 00:45-00:58Z 2026-10-13: apply_migration timed out four times, even for a plain create table with grants; nothing landed, no lock or active query, execute_sql reads answering. Same night as S374's six. Open Asks Sheet 72 cards 1 and 3 hand both pending structure changes to Sam as pastes.","detail":null,"plain":"For two sessions in a row the tool that changes the database's structure has stopped answering, even for a tiny change. Reading works. Sam has both pending changes on his decision sheet to paste himself, or the next session tries the tool again.","tags":["supabase","mcp","pitfall","migration"],"source":"S375 SkyTally tool results","related":["apply-migration-timeouts-2026-10-12"],"status":"proposed"}
]$json$::jsonb)
  as x(slug text, kind text, title text, summary text, detail text, plain text, tags text[], source text, related text[], status text)
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select m.id, 'SkyTallyS375', 'create', 'checkpoint auto-write', to_jsonb(m) from public.cpl_memory m
where m.author = 'SkyTallyS375' and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.actor = 'SkyTallyS375');
select m.slug, m.kind, m.status, (select count(*) from public.cpl_memory_log l where l.memory_id = m.id) as logs
from public.cpl_memory m where m.author = 'SkyTallyS375' order by m.created_at;
